from collections import deque
G=A[1:-1,1:-1]
def comps(pred):
 h,w=G.shape; seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or not pred(G[r,c]): continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(x+dx,y+dy)
     if 0<=z[0]<h and 0<=z[1]<w and z not in seen and pred(G[z]):seen.add(z);q.append(z)
   cs.append(cells)
 return cs
cs=comps(lambda x:x!=8)
